from scipy.optimize import least_squares, differential_evolution
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
SS=np.sum((y-y.mean())**2)
def base(p):
    return p[0]/t + p[1]*(A/(1+p[2]*A))*t**3 + p[3]*np.sin(p[4]*np.sqrt(A))*t**1.5
def f(p): return p[5]*t**p[6]*A**p[7]*np.exp(-p[8]*A)
def full(p):
    m=base(p)+f(p)
    return np.where(np.isfinite(m),m,1e6)
def sse(p): return np.sum((full(p)-y)**2)
bounds=[(-20,20),(-5,5),(-5,5),(-5,5),(-5,5),(-20,20),(-3,3),(-3,3),(-4,4)]
de=differential_evolution(sse,bounds,seed=3,maxiter=200,tol=1e-14,polish=False,popsize=20)
q=least_squares(lambda p: full(p)-y, de.x)
print(round(2*q.cost/SS,9), np.round(q.x,5))
